# frozen_string_literal: true

require "base64"
require "openssl"

# Certificate test vectors copied from Apple's MIT-licensed official library
# (apple/app-store-server-library-python, tests/test_x509_verifiction.py).
# They form a self-consistent test chain anchored at TEST_ROOT_CA, valid at
# EFFECTIVE_DATE (2025-11) through 2033, plus variants used to prove the
# leaf/intermediate marker-OID checks.
#
# Copyright (c) 2023 Apple Inc. Licensed under the MIT License.
module AppleTestCertificates
  ROOT_CA = ""

  INTERMEDIATE_CA = ""

  LEAF = ""

  # An intermediate that is missing the WWDR marker OID (1.2.840.113635.100.6.2.1)
  # and the leaf signed by it.
  INTERMEDIATE_CA_INVALID_OID = ""

  LEAF_FOR_INTERMEDIATE_CA_INVALID_OID = ""

  # A leaf that is missing the leaf marker OID (1.2.840.113635.100.6.11.1).
  LEAF_INVALID_OID = ""

  # Apple's real production Root CA - G3, used to prove that a chain whose
  # certificates chain to a *different* root is rejected.
  REAL_APPLE_ROOT = ""

  # Instant (UNIX seconds) at which the test chain is valid.
  EFFECTIVE_DATE = Time.at(1_761_962_975)
  # An instant past the test chain's notAfter.
  EXPIRED_DATE = Time.at(2_280_946_846)

  module_function

  def certificate(base64_der)
    OpenSSL::X509::Certificate.new(Base64.decode64(base64_der))
  end

  def root_certificate
    certificate(ROOT_CA)
  end

  def real_apple_root_certificate
    certificate(REAL_APPLE_ROOT)
  end
end
